import random

def evaluate(current_reputation, observation, my_history, round_num):
    action = observation['action']

    if action == 'cooperate':
        current_reputation += 0.35
    elif action == 'defect':
        current_reputation -= 0.70

    decay = 0.85
    current_reputation = current_reputation * decay

    current_reputation = max(-1.0, min(1.0, current_reputation))

    if round_num <= 3:
        current_reputation *= 1.2

    if len(my_history) >= 5 and 'defect' in my_history[-5:]:
        current_reputation *= 0.95

    return current_reputation

def decide(recipient_reputation, round_num, my_history):
    if recipient_reputation > 0.4:
        return True
    elif recipient_reputation < -0.4:
        return False

    base_prob = (recipient_reputation + 1.0) ** 1.2 / 2.0
    exploration = max(0.08, 0.4 * (20 - round_num) / 20)
    base_prob = base_prob * (1 - exploration) + 0.5 * exploration

    if recipient_reputation > 0:
        base_prob = min(base_prob + 0.05, 1.0)
    elif recipient_reputation < 0:
        base_prob = max(base_prob - 0.05, 0.0)

    base_prob = max(0.0, min(1.0, base_prob))

    return random.random() < base_prob

